    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$The rotational mold's cost, from its size (eMithran assumption: memory/Roto & blow molding gives only its limits, rotoMoldingMinMoldCost to rotoMoldingMaxMoldCost, and its dial rotoMoldingMoldCostComp): the limit range scaled by the mold's surface over the surface of the largest mold the largest carousel swings, never above the upper limit, times the dial and the region's multiplier (regionMultiplier).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Minimum Cost$q$, $q$Minimum Cost (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Maximum Cost$q$, $q$Maximum Cost (USD)$q$, $q$number$q$, $q$USD$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Cost Dial$q$, $q$Cost Dial$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Region Multiplier$q$, $q$Region Multiplier$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Size$q$, $q$Size$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Largest Size$q$, $q$Largest Size$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Size Share$q$, $q$Size Share$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$min(1, {Size} / {Largest Size})$q$, 7, false),
    (v_id, $q$Tool Cost$q$, $q$Tool Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q$({Minimum Cost} + ({Maximum Cost} - {Minimum Cost}) * {Size Share}) * {Cost Dial} * {Region Multiplier}$q$, 8, false);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Roto & Blow Molding - Cooling$q$, 9, 0),
    ($q$Roto & Blow Molding - Inflate$q$, 4, 0),
    ($q$Roto & Blow Molding - Blow mold cavities$q$, 13, 0),
    ($q$Roto & Blow Molding - Extrusion blow mold$q$, 9, 1),
    ($q$Roto & Blow Molding - Molds per arm$q$, 17, 0),
    ($q$Roto & Blow Molding - Load and unload$q$, 17, 0),
    ($q$Roto & Blow Molding - Rotational mold$q$, 8, 1),
    ($q$Roto & Blow Molding - Grind$q$, 4, 1),
    ($q$Roto & Blow Molding - Router$q$, 8, 1),
    ($q$Roto & Blow Molding - Saw$q$, 5, 1),
    ($q$Roto & Blow Molding - Blow molded material$q$, 13, 0),
    ($q$Roto & Blow Molding - Rotomolded material$q$, 12, 0),
    ($q$Roto & Blow Molding - Blow mold tooling$q$, 8, 0),
    ($q$Roto & Blow Molding - Trim tooling$q$, 8, 0),
    ($q$Roto & Blow Molding - Rotational mold tooling$q$, 8, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Roto & Blow Molding$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1108: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
